186	void EventListenerPhysicsContact::onEvent(EventCustom* event)
187	{
188	    PhysicsContact* contact = dynamic_cast<PhysicsContact*>(event);
189	    if (contact == nullptr)
190	    {
191	        return;
192	    }
193	    bool canNotify = hitTest(contact->getShapeA(), contact->getShapeB());
194	    if (!canNotify)
195	    {
196	        contact->setResult(true);
197	        return;
198	    }
199	    // Minimal callback routing for hollowed base.
200	    if (contact->getEventCode() == PhysicsContact::EventCode::BEGIN && onContactBegin != nullptr)
201	    {
202	        contact->setResult(onContactBegin(*contact));
203	        return;
204	    }
205	    if (contact->getEventCode() == PhysicsContact::EventCode::PRESOLVE && onContactPreSolve != nullptr)
206	    {
207	        PhysicsContactPreSolve solve(contact->_contactInfo);
208	        contact->setResult(onContactPreSolve(*contact, solve));
209	        return;
210	    }
211	    if (contact->getEventCode() == PhysicsContact::EventCode::POSTSOLVE && onContactPostSolve != nullptr)
212	    {
213	        PhysicsContactPostSolve solve(contact->_contactInfo);
214	        onContactPostSolve(*contact, solve);
215	        return;
216	    }
217	    if (contact->getEventCode() == PhysicsContact::EventCode::SEPARATE && onContactSeparate != nullptr)
218	    {
219	        onContactSeparate(*contact);
220	    }
221	    contact->setResult(true);
222	}
